import{_ as o,c as e,o as t,a4 as c}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q19：HTTP 缓存策略（强缓存与协商缓存）","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q19.md","filePath":"frontend/q19.md","lastUpdated":null}'),d={name:"frontend/q19.md"},r=c('<h1 id="q19-http-缓存策略-强缓存与协商缓存" tabindex="-1">Q19：HTTP 缓存策略（强缓存与协商缓存） <a class="header-anchor" href="#q19-http-缓存策略-强缓存与协商缓存" aria-label="Permalink to &quot;Q19：HTTP 缓存策略（强缓存与协商缓存）&quot;">​</a></h1><p>缓存是前端性能优化的核心。按流程判断：</p><ol><li><p><strong>首先检查强缓存（不发请求）</strong></p><ul><li><strong><code>Cache-Control</code></strong>（HTTP/1.1，优先级更高）：如 <code>max-age=3600</code> 代表 3600 秒内有效，<code>public</code> 可被任何缓存，<code>private</code> 仅浏览器，<code>no-cache</code> 需协商，<code>no-store</code> 不缓存。</li><li><strong><code>Expires</code></strong>（HTTP/1.0）：绝对过期时间，有缺点（服务器时间偏差）。</li></ul><p>若命中强缓存，返回状态码 <code>200 (from memory/disk cache)</code>。</p></li><li><p><strong>强缓存失效，走协商缓存（发请求询问）</strong></p><ul><li><strong><code>Last-Modified</code> / <code>If-Modified-Since</code></strong>：服务器返回文件最后修改时间，客户端下次请求时带上此字段。服务器比较，若未变则返回 <code>304</code>，不变则返回新资源。</li><li><strong><code>ETag</code> / <code>If-None-Match</code></strong>：更精准的内容唯一标识，优先级高于 <code>Last-Modified</code>。解决了文件内容无变化但时间变了的问题。</li><li>命中则返回 <code>304 Not Modified</code>，浏览器继续从缓存加载。</li></ul></li></ol><p><strong>缓存位置</strong>：内存缓存（from memory cache，快速，关闭即清）、硬盘缓存（from disk cache，持久）、Service Worker 等。</p>',4),a=[r];function n(i,s,l,p,_,f){return t(),e("div",null,a)}const g=o(d,[["render",n]]);export{m as __pageData,g as default};
